files.ontology.ttl:
@prefix ex: <https://example.org/ontology/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
ex:Employee a owl:Class ; rdfs:label "员工"@zh .
ex:Department a owl:Class ; rdfs:label "部门"@zh .
ex:belongsToDepartment a owl:ObjectProperty ;
    rdfs:label "所属部门"@zh ;
    rdfs:domain ex:Employee ; rdfs:range ex:Department .

@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
ex:employeeId a owl:DatatypeProperty ; rdfs:label "员工编号"@zh ; rdfs:domain ex:Employee ; rdfs:range xsd:string .
ex:employeeName a owl:DatatypeProperty ; rdfs:label "员工姓名"@zh ; rdfs:domain ex:Employee ; rdfs:range xsd:string .
ex:departmentId a owl:DatatypeProperty ; rdfs:label "部门编号"@zh ; rdfs:domain ex:Department ; rdfs:range xsd:string .
ex:departmentName a owl:DatatypeProperty ; rdfs:label "部门名称"@zh ; rdfs:domain ex:Department ; rdfs:range xsd:string .

files.instances.ttl:
@prefix dept: <https://example.org/data/hr/Department/> .
@prefix emp: <https://example.org/data/hr/Employee/> .
@prefix ex: <https://example.org/ontology/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

emp:E-001 a ex:Employee ;
    ex:belongsToDepartment dept:D-01 ;
    ex:employeeId "E-001"^^xsd:string ;
    ex:employeeName "林晓"^^xsd:string .

emp:E-002 a ex:Employee ;
    ex:belongsToDepartment dept:D-02 ;
    ex:employeeId "E-002"^^xsd:string ;
    ex:employeeName "陈雨"^^xsd:string .

emp:E-003 a ex:Employee ;
    ex:belongsToDepartment dept:D-01 ;
    ex:employeeId "E-003"^^xsd:string ;
    ex:employeeName "周宁"^^xsd:string .

dept:D-02 a ex:Department ;
    ex:departmentId "D-02"^^xsd:string ;
    ex:departmentName "运维部"^^xsd:string .

dept:D-01 a ex:Department ;
    ex:departmentId "D-01"^^xsd:string ;
    ex:departmentName "研发部"^^xsd:string .

files.shapes.ttl:
@prefix ex: <https://example.org/ontology/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
ex:EmployeeShape a sh:NodeShape ; sh:targetClass ex:Employee ;
 sh:property [ sh:path ex:employeeId ; sh:datatype xsd:string ; sh:minLength 1 ; sh:minCount 1 ; sh:maxCount 1 ] ;
 sh:property [ sh:path ex:employeeName ; sh:datatype xsd:string ; sh:minLength 1 ; sh:minCount 1 ; sh:maxCount 1 ] ;
 sh:property [ sh:path ex:belongsToDepartment ; sh:class ex:Department ; sh:minCount 1 ; sh:maxCount 1 ] .
ex:DepartmentShape a sh:NodeShape ; sh:targetClass ex:Department ;
 sh:property [ sh:path ex:departmentId ; sh:datatype xsd:string ; sh:minLength 1 ; sh:minCount 1 ; sh:maxCount 1 ] ;
 sh:property [ sh:path ex:departmentName ; sh:datatype xsd:string ; sh:minLength 1 ; sh:minCount 1 ; sh:maxCount 1 ] .
